using System;using System.IO;using System.Reflection;using System.Collections.Generic;using System.Threading.Tasks;using UnityEngine;using UnityEngine.UI;using UnityEngine.SceneManagement;using Mavis;
public static class AutoQaVitalsRegression{
 const BindingFlags F=BindingFlags.Instance|BindingFlags.NonPublic;
 static T Get<T>(object o,string n)=>(T)o.GetType().GetField(n,F).GetValue(o);
 public static async Task<object> Run(string take){
 if(!Application.isPlaying||SceneManager.sceneCount!=1||!string.IsNullOrEmpty(SceneManager.GetActiveScene().path)||CombatFeelPreview.Player)throw new Exception("Isolated unowned Play required");
 var rows=new List<object>();string error=null;GameObject ui=null;void Check(bool ok,string label)=>rows.Add(new{ok,label});
 try{CombatFeelPreview.Spawn();var actor=CombatFeelPreview.Player;var motor=actor.GetComponent<ThirdPersonPlayerController>();motor.ExternalControlLock=true;int f=Time.frameCount+5;while(Time.frameCount<f)await Task.Delay(5);ui=new GameObject("AUTO_QA Vitals",typeof(RectTransform),typeof(Canvas),typeof(CanvasScaler));var hud=ui.AddComponent<PlayerVitalsHUD>();hud.enabled=false;var hp=actor.GetComponent<PlayerHealth>();var stamina=actor.GetComponent<PlayerStamina>();var update=typeof(PlayerVitalsHUD).GetMethod("Update",F);var refresh=typeof(PlayerVitalsHUD).GetMethod("RefreshBars",F);var group=Get<CanvasGroup>(hud,"canvasGroup");
 Check(Get<PlayerHealth>(hud,"health")==hp,"Binds actual preview player");Check(group&&!group.blocksRaycasts&&!group.interactable,"HUD does not capture gameplay input");Check(ui.GetComponent<CanvasScaler>().referenceResolution==new Vector2(1920,1080),"Reference resolution preserved");
 foreach(float ratio in new[]{1f,.5f,.01f,0f}){hp.currentHealth=hp.maxHealth*ratio;stamina.currentStamina=stamina.maxStamina*ratio;refresh.Invoke(hud,new object[]{true});var h=Get<Image>(hud,"healthFill");var s=Get<Image>(hud,"staminaFill");Check(Mathf.Abs(h.rectTransform.anchorMax.x-ratio)<.001f&&h.enabled==(ratio>0),"HP fill / zero visibility "+ratio);Check(Mathf.Abs(s.rectTransform.anchorMax.x-ratio)<.001f&&s.enabled==(ratio>0),"SP fill / zero visibility "+ratio);Check(Get<Text>(hud,"hpValue").text==Mathf.CeilToInt(hp.currentHealth)+" / "+Mathf.CeilToInt(hp.maxHealth),"HP numeric label "+ratio);}
 hp.currentHealth=hp.maxHealth;update.Invoke(hud,null);Check(group.alpha==1,"Alive enabled actor shows HUD");motor.enabled=false;update.Invoke(hud,null);Check(group.alpha==0,"Disabled movement hides HUD");motor.enabled=true;hp.currentHealth=0;update.Invoke(hud,null);Check(group.alpha==0,"Dead actor hides HUD");hp.currentHealth=hp.maxHealth;update.Invoke(hud,null);Check(group.alpha==1,"Alive recovery restores HUD");
 }catch(Exception e){error=e.ToString();}finally{if(ui)UnityEngine.Object.DestroyImmediate(ui);CombatFeelPreview.Clear();}var result=new{error,rows};File.WriteAllText("AUTO_QA/Evidence/"+take+".json",Newtonsoft.Json.JsonConvert.SerializeObject(result,Newtonsoft.Json.Formatting.Indented));return result;
 }
}
